import type { ApiEmailCategory } from '@/api/types.js';

const CATEGORIES: readonly ApiEmailCategory[] = ['nudges', 'weekly', 'news', 'all'];

/**
 * The category an e-mail's footer link names (`c`). Absent, or anything this
 * page does not know, is every category: that is what the single link in
 * older e-mails promised, and somebody who pressed "unsubscribe" asked for
 * less e-mail, not more.
 */
export function categoryOf(value: string | null): ApiEmailCategory {
  return CATEGORIES.find((category) => category === value) ?? 'all';
}
