import { useCallback, useEffect, useRef, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { email as emailApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import type { ApiEmailCategory, ApiEmailPreferences } from '@/api/types.js';
import { Icon } from '@/components/ui/Icon.js';
import { Skeleton } from '@/components/ui/Skeleton.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { useAuth } from '@/features/auth/session.js';
import { settingsPath } from '@/features/settings/paths.js';
import { SwitchRow } from '@/features/settings/SettingsKit.js';
import settingsStyles from '@/features/settings/Settings.module.css';
import { syncSoon } from '@/sync/store.js';
import { categoryOf } from './category.js';
import styles from './Unsubscribe.module.css';

/** The three switches, as the page and the server name them. */
type Switch = 'nudges' | 'weekly' | 'news';
type Switches = Pick<ApiEmailPreferences, Switch>;

/** Why a call did not land, in the words the page has for it. */
type Trouble = 'invalid' | 'offline' | 'busy' | 'failed';

/** What following the link did. */
type Outcome = { kind: 'working' } | { kind: 'done' } | { kind: 'trouble'; trouble: Trouble };

/** The switches below the outcome. */
type Prefs =
  | { kind: 'waiting' }
  | { kind: 'ready'; shown: Switches; suppressed: boolean }
  | { kind: 'trouble'; trouble: Trouble };

const DONE_TITLE: Record<ApiEmailCategory, MessageKey> = {
  nudges: 'emailPrefs.doneNudges',
  weekly: 'emailPrefs.doneWeekly',
  news: 'emailPrefs.doneNews',
  all: 'emailPrefs.doneAll',
};

const ROWS: readonly { key: Switch; label: MessageKey; note: MessageKey }[] = [
  { key: 'nudges', label: 'settings.emailNudges', note: 'settings.emailNudgesNote' },
  { key: 'weekly', label: 'settings.weekly', note: 'settings.weeklyNote' },
  { key: 'news', label: 'settings.news', note: 'settings.newsNote' },
];

function troubleOf(error: unknown): Trouble {
  if (isApiError(error, 'offline')) return 'offline';
  if (isApiError(error, 'tooMany')) return 'busy';
  // A token that is not ours (`link_invalid`), or an account that is gone.
  if (isApiError(error, 'invalid') || isApiError(error, 'notFound')) return 'invalid';
  return 'failed';
}

const TROUBLE_TEXT: Record<Trouble, MessageKey> = {
  invalid: 'emailPrefs.invalid',
  offline: 'emailPrefs.offline',
  busy: 'emailPrefs.busy',
  failed: 'emailPrefs.failed',
};

/**
 * Where the footer link of a Lexpad e-mail lands. It asks for nothing: no
 * session, no password, no "are you sure". Following it turns off what the
 * link names (`c`: the reminders, the weekly summary, product news, or all
 * three), says so in plain words, and then shows the three switches so the
 * reader can change anything else from the same page, signed in or not.
 *
 * Account e-mails (confirmations, resets, security and money notices) have
 * no switch and the page says they keep coming, so nobody thinks they have
 * broken their account. An address the server has stopped writing to after
 * bounces or a spam report is said out loud, with the way to change it,
 * because switches that cannot reach anybody would otherwise be a lie.
 */
export function Unsubscribe(): React.JSX.Element {
  const [params] = useSearchParams();
  const token = params.get('token') ?? '';
  const category = categoryOf(params.get('c'));
  const status = useAuth((state) => state.status);

  const [outcome, setOutcome] = useState<Outcome>(
    token === '' ? { kind: 'trouble', trouble: 'invalid' } : { kind: 'working' },
  );
  const [prefs, setPrefs] = useState<Prefs>({ kind: 'waiting' });
  const [note, setNote] = useState<{ text: string; failed: boolean } | undefined>();

  // What the server last confirmed, and the writes still on their way.
  // Writes go one at a time so their answers arrive in order; the screen
  // shows the reader's choice at once and the server's word once the last
  // one is in, or the last confirmed state again when one fails.
  const confirmed = useRef<Switches | undefined>(undefined);
  const queue = useRef<Promise<void>>(Promise.resolve());
  const pending = useRef(0);

  /** Brings this device's copy up to date when the reader is signed in here. */
  const refreshHere = useCallback((): void => {
    if (useAuth.getState().status !== 'ready') return;
    void syncSoon().catch(() => undefined);
    void useAuth
      .getState()
      .refreshUser()
      .catch(() => undefined);
  }, []);

  const loadPrefs = useCallback(async (): Promise<void> => {
    setPrefs({ kind: 'waiting' });
    try {
      const answer = await emailApi.preferences(token);
      confirmed.current = pick(answer);
      setPrefs({ kind: 'ready', shown: pick(answer), suppressed: answer.suppressed });
    } catch (error) {
      setPrefs({ kind: 'trouble', trouble: troubleOf(error) });
    }
  }, [token]);

  const follow = useCallback(async (): Promise<void> => {
    setOutcome({ kind: 'working' });
    try {
      // An absent `c` is sent as no category, which the server reads as all.
      await emailApi.unsubscribe(token, params.has('c') ? category : undefined);
    } catch (error) {
      setOutcome({ kind: 'trouble', trouble: troubleOf(error) });
      return;
    }
    setOutcome({ kind: 'done' });
    refreshHere();
    await loadPrefs();
  }, [token, category, params, refreshHere, loadPrefs]);

  // Once per page: the same link followed twice says the same thing, and
  // React's development double effect must not send it twice.
  const started = useRef(false);
  useEffect(() => {
    if (started.current || token === '') return;
    started.current = true;
    void follow();
  }, [follow, token]);

  // Offline when the link was opened: try again by itself once the
  // connection is back, as well as on the button.
  useEffect(() => {
    if (outcome.kind !== 'trouble' || outcome.trouble !== 'offline') return;
    const retry = (): void => {
      void follow();
    };
    window.addEventListener('online', retry);
    return () => {
      window.removeEventListener('online', retry);
    };
  }, [outcome, follow]);

  const change = (patch: Partial<Switches>): void => {
    setPrefs((current) =>
      current.kind === 'ready' ? { ...current, shown: { ...current.shown, ...patch } } : current,
    );
    setNote(undefined);
    pending.current += 1;
    const write = async (): Promise<void> => {
      try {
        const answer = await emailApi.setPreferences({ token, ...patch });
        confirmed.current = pick(answer);
        pending.current -= 1;
        if (pending.current === 0) {
          setPrefs({ kind: 'ready', shown: pick(answer), suppressed: answer.suppressed });
          const everythingOff = !answer.nudges && !answer.weekly && !answer.news;
          setNote({ text: t(everythingOff ? 'emailPrefs.onlyAccount' : 'emailPrefs.saved'), failed: false });
        }
        refreshHere();
      } catch (error) {
        pending.current -= 1;
        const trouble = troubleOf(error);
        if (trouble === 'invalid') {
          setOutcome({ kind: 'trouble', trouble });
          return;
        }
        const back = confirmed.current;
        if (back !== undefined) {
          setPrefs((current) => (current.kind === 'ready' ? { ...current, shown: back } : current));
        }
        setNote({
          text: t(trouble === 'offline' ? 'emailPrefs.saveOffline' : TROUBLE_TEXT[trouble]),
          failed: true,
        });
      }
    };
    queue.current = queue.current.then(write, write);
  };

  const failed = outcome.kind === 'trouble';
  const title =
    outcome.kind === 'done'
      ? t(DONE_TITLE[category])
      : outcome.kind === 'working'
        ? t('emailPrefs.working')
        : outcome.trouble === 'invalid'
          ? t('emailPrefs.invalidTitle')
          : outcome.trouble === 'offline'
            ? t('emailPrefs.offlineTitle')
            : t('emailPrefs.failedTitle');

  return (
    <main className={styles.wrap}>
      <div className={styles.brand}>
        <div className={styles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <span className={styles.name}>{t('app.name')}</span>
      </div>

      <section className={styles.outcome} aria-labelledby="email-outcome">
        <h1 id="email-outcome" className={styles.title}>
          {title}
        </h1>
        {outcome.kind === 'working' && (
          <p className={styles.lead} role="status">
            {t('state.loading')}
          </p>
        )}
        {outcome.kind === 'done' && (
          <p className={styles.lead} role="status">
            {t('emailPrefs.doneBody')}
          </p>
        )}
        {failed && (
          <>
            <p className={styles.error} role="alert">
              {t(TROUBLE_TEXT[outcome.trouble])}
            </p>
            {outcome.trouble !== 'invalid' && (
              <button
                type="button"
                className={styles.button}
                onClick={() => {
                  void follow();
                }}
              >
                {t('action.retry')}
              </button>
            )}
          </>
        )}
      </section>

      {outcome.kind === 'done' && (
        <section className={styles.switches} aria-labelledby="email-switches">
          <h2 id="email-switches" className={settingsStyles.sectionTitle}>
            {t('emailPrefs.heading')}
          </h2>
          {prefs.kind === 'waiting' && (
            <div className={styles.waiting}>
              <Skeleton lines={3} />
              <p className="sr-only" role="status">
                {t('state.loading')}
              </p>
            </div>
          )}
          {prefs.kind === 'trouble' && (
            <div className={styles.problem}>
              <p className={styles.error} role="alert">
                {t(prefs.trouble === 'invalid' ? 'emailPrefs.invalid' : 'emailPrefs.prefsFailed')}
              </p>
              {prefs.trouble !== 'invalid' && (
                <button
                  type="button"
                  className={styles.quiet}
                  onClick={() => {
                    void loadPrefs();
                  }}
                >
                  {t('action.retry')}
                </button>
              )}
            </div>
          )}
          {prefs.kind === 'ready' && (
            <>
              {prefs.suppressed && (
                <div className={styles.suppressed} role="note">
                  <p className={styles.suppressedTitle}>{t('emailPrefs.suppressedTitle')}</p>
                  <p className={styles.suppressedText}>{t('emailPrefs.suppressed')}</p>
                  <Link to={settingsPath('account')} className={styles.inlineLink}>
                    {t('emailPrefs.changeAddress')}
                  </Link>
                </div>
              )}
              <div className={settingsStyles.group}>
                {ROWS.map((row) => (
                  <div key={row.key} className={styles.switchBlock}>
                    <SwitchRow
                      label={t(row.label)}
                      checked={prefs.shown[row.key]}
                      onChange={(on) => {
                        change({ [row.key]: on });
                      }}
                    />
                    <p className={settingsStyles.groupNote}>{t(row.note)}</p>
                  </div>
                ))}
              </div>
              {prefs.shown.nudges || prefs.shown.weekly || prefs.shown.news ? (
                <button
                  type="button"
                  className={styles.button}
                  onClick={() => {
                    change({ nudges: false, weekly: false, news: false });
                  }}
                >
                  {t('emailPrefs.stopAll')}
                </button>
              ) : (
                <p className={styles.lead}>{t('emailPrefs.onlyAccount')}</p>
              )}
              {note !== undefined && (
                <p className={note.failed ? styles.error : styles.saved} role="status">
                  {note.text}
                </p>
              )}
            </>
          )}
        </section>
      )}

      <nav className={styles.links} aria-label={t('emailPrefs.more')}>
        <Link to={settingsPath('notifications')} className={styles.inlineLink}>
          {t('emailPrefs.allSettings')}
        </Link>
        {status === 'ready' && (
          <Link to="/" className={styles.inlineLink}>
            {t('emailPrefs.openNotebook')}
          </Link>
        )}
      </nav>
    </main>
  );
}

function pick(answer: ApiEmailPreferences): Switches {
  return { nudges: answer.nudges, weekly: answer.weekly, news: answer.news };
}
